package tv.vela.launcher;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;

/** Remote navigation and actual bounds, on an owned emulator with an isolated local profile. */
public final class AndroidUiUxTest extends Instrumentation {
    private String captureLanguage="es";private Context context;private Activity activity;private String previous,profile,phase="setup";private boolean empty;
    public static final class Empty extends Activity {}
    @Override public Activity newActivity(ClassLoader loader,String name,Intent intent)throws InstantiationException,IllegalAccessException,ClassNotFoundException{return empty?new Empty():super.newActivity(loader,name,intent);}
    static void check(boolean value,String why){if(!value)throw new AssertionError(why);}
    Object field(Object target,String key)throws Exception{for(Class<?> type=target.getClass();type!=null;type=type.getSuperclass())try{Field f=type.getDeclaredField(key);f.setAccessible(true);return f.get(target);}catch(NoSuchFieldException absent){}throw new NoSuchFieldException(key);}
    void call(Object target,String key,Class<?>[] types,Object... args){try{for(Class<?> type=target.getClass();type!=null;type=type.getSuperclass())try{Method m=type.getDeclaredMethod(key,types);m.setAccessible(true);m.invoke(target,args);return;}catch(NoSuchMethodException absent){}throw new NoSuchMethodException(key);}catch(Exception failure){throw new RuntimeException(failure);}}
    void ui(Runnable action){Throwable[] failure={null};runOnMainSync(()->{try{action.run();}catch(Throwable t){failure[0]=t;}});waitForIdleSync();if(failure[0]!=null)throw new AssertionError(failure[0]);}
    void key(int value){sendKeyDownUpSync(value);waitForIdleSync();}
    void capture(String name)throws Exception{Thread.sleep(300);Bitmap b=getUiAutomation().takeScreenshot();check(b!=null&&b.getWidth()==3840,"Native 4K capture required");try(OutputStream out=new FileOutputStream(new File(context.getExternalFilesDir(null),"uiux-"+name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
    void nonOverlapping(List<View> rows){for(int i=0;i<rows.size();i++){View a=rows.get(i);check(a.getHeight()>0,"An option has no hit area");for(int j=i+1;j<rows.size();j++){View b=rows.get(j);if(a.getParent()==b.getParent())check(!Rect.intersects(new Rect(a.getLeft(),a.getTop(),a.getRight(),a.getBottom()),new Rect(b.getLeft(),b.getTop(),b.getRight(),b.getBottom())),"Settings options overlap: "+i+" / "+j);}}}
    public void onCreate(Bundle args){super.onCreate(args);captureLanguage=args.getString("language","es");start();}
    public void onStart(){Bundle result=new Bundle();context=getTargetContext();try{
        try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("getprop ro.kernel.qemu");InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){check(in.read()=='1',"Owned emulator required");}
        boolean lite=context.getPackageName().endsWith(".lite");previous=VelaWorkspace.active(context);profile=VelaWorkspace.create(context,"Vela · Demo");VelaWorkspace.select(context,profile);L10n.choose(context,captureLanguage);Ui.init(context);VelaWorkspace.prefs(context,lite?"lite_updates":"updates").edit().putBoolean("automatic",false).commit();context.getSharedPreferences("personalization",Context.MODE_PRIVATE).edit().putBoolean("initialized",true).putBoolean("complete",true).commit();
        Intent launch=new Intent().setClassName(context.getPackageName(),"tv.vela.launcher."+(lite?"LiteHomeActivity":"HomeActivity")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=startActivitySync(launch);
        phase="integrated-settings";Object settings;
        if(lite){ui(()->call(activity,"show",new Class[]{int.class,boolean.class},3,false));settings=field(activity,"settingsView");}
        else{Object home=field(activity,"home");ui(()->call(home,"openPanel",new Class[]{Intent.class},new Intent().setClassName(context.getPackageName(),"tv.vela.launcher.SettingsActivity")));settings=field(field(field(home,"panels"),"screen"),"view");}
        check(settings!=null,"Settings left the integrated shell");View[] categories=(View[])field(settings,"categories");ui(categories[0]::requestFocus);capture("01-settings");Object owner=lite?activity:field(activity,"home");View rail=(View)field(owner,lite?"rail":"sidebar"),heading=(View)field(owner,lite?"heading":"pageTitle");View settingNav=lite?((View[])field(owner,"navigation"))[3]:((List<View>)field(owner,"sideButtons")).get(7);ui(settingNav::requestFocus);Thread.sleep(180);Rect railBounds=new Rect(),headingBounds=new Rect();ui(()->{rail.getGlobalVisibleRect(railBounds);heading.getGlobalVisibleRect(headingBounds);});check(headingBounds.left>railBounds.right,"Embedded page header remains underneath expanded navigation");capture("04-settings-navigation");key(KeyEvent.KEYCODE_DPAD_RIGHT);Thread.sleep(150);ui(categories[1]::requestFocus);key(KeyEvent.KEYCODE_DPAD_RIGHT);List<View> rows=(List<View>)field(settings,lite?"controls":"rows");nonOverlapping(rows);check(rows.size()>=6,"Appearance controls disappeared");View last=rows.get(rows.size()-1);ui(last::requestFocus);key(KeyEvent.KEYCODE_DPAD_LEFT);check(categories[1].hasFocus(),"Left did not return to the appearance category");key(KeyEvent.KEYCODE_DPAD_RIGHT);check(last.hasFocus(),"Returning to options discarded the last focused row");Rect visible=new Rect();check(last.getGlobalVisibleRect(visible)&&visible.height()>=last.getHeight()/2,"Last appearance option is clipped or unreachable");ui(categories[1]::requestFocus);capture("02-appearance");
        phase="continuous-menu-canvas";View canvas=(View)field(owner,lite?"stage":"pageBackdrop");for(int tab=0;tab<categories.length;tab++){final View category=categories[tab];ui(category::requestFocus);check(canvas.isShown()&&canvas.getScaleX()==1f&&canvas.getTranslationX()==0f,"Changing settings tab moved or hid the full-screen canvas");}ui(settingNav::requestFocus);Thread.sleep(180);capture("05-continuous-settings");key(KeyEvent.KEYCODE_DPAD_RIGHT);
        phase="tools-focus-memory";ui(()->((VelaHub.Owner)activity).tools(2));VelaHub hub=(VelaHub)field(activity,"hub");List<View> controls=(List<View>)field(hub,"controls");View remembered=controls.get(1);ui(remembered::requestFocus);key(KeyEvent.KEYCODE_DPAD_LEFT);key(KeyEvent.KEYCODE_DPAD_UP);key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_RIGHT);controls=(List<View>)field(hub,"controls");check(controls.get(1).hasFocus(),"Tool categories forgot the last focused action");capture("03-reading");check(hub.getBackground()==null,"Embedded tools still paint a cropped rectangular backdrop");ui(settingNav::requestFocus);Thread.sleep(180);check(canvas.getScaleX()==1f&&canvas.isShown(),"Tools preview moved the wallpaper");capture("06-continuous-tools");key(KeyEvent.KEYCODE_DPAD_RIGHT);
        phase="complete-synopsis";ui(activity::finish);empty=true;activity=startActivitySync(launch);StringBuilder story=new StringBuilder();for(int i=0;i<32;i++)story.append("Una sinopsis extensa que debe poder leerse con el mando sin perder información. ");story.append("Fin de la sinopsis.");VelaContentDetails[] sheet={null};ui(()->{VelaReading.Stage stage=new VelaReading.Stage(activity,1790,940,true);FrameLayout root=new FrameLayout(activity);root.setBackgroundColor(VelaTheme.BACKGROUND);stage.addView(root);sheet[0]=new VelaContentDetails(activity,"Información","2026 · Película",story.toString(),.5f);FrameLayout.LayoutParams bounds=new FrameLayout.LayoutParams(1390,790);bounds.leftMargin=180;bounds.topMargin=70;root.addView(sheet[0],bounds);sheet[0].action("Volver","",()->{});activity.setContentView(stage);});ScrollView synopsis=(ScrollView)field(sheet[0],"synopsis");ui(synopsis::requestFocus);check(sheet[0].description.getCurrentTextColor()==VelaTheme.INK,"Focused synopsis lost readable contrast");check(sheet[0].description.getHeight()>synopsis.getHeight(),"Long synopsis was truncated instead of scrollable");for(int i=0;i<4;i++)key(KeyEvent.KEYCODE_DPAD_DOWN);check(synopsis.getScrollY()>0,"D-pad cannot scroll the synopsis");check(sheet[0].description.getText().toString().endsWith("Fin de la sinopsis."),"Synopsis text was shortened");
        result.putString("result","PASS integrated settings, non-overlapping option bounds, reachable final appearance row, settings/tool focus restoration and complete remote-scrollable synopsis in the native UI. Isolated profile; no physical TV or account contacted.");
    }catch(Throwable failure){result.putString("error",phase+"\n"+android.util.Log.getStackTraceString(failure));}finally{try{if(activity!=null)ui(activity::finish);if(profile!=null){VelaWorkspace.select(context,previous);VelaWorkspace.delete(context,profile);}}catch(Exception ignored){}}finish(result.containsKey("error")?1:-1,result);}
}
